INSERT INTO `cases` VALUES (1,'AJ','KES-Petaling/2026/04/0001',NULL,2026,1,'Petaling',NULL,59,97,97,NULL,26,NULL,'FNA',NULL,'Selesai Dengan Kes',NULL,NULL,NULL,NULL,NULL,'ada','Pegawai Penguatkuasa Agama',1,1,0,'2026-04-25 00:15:00','2026-04-25 00:20:00','2026-04-25 02:35:00','2026-04-29 09:00:00','2026-12-09','2026-04-25 00:45:00',NULL,NULL,'LAKSANA TINDAKAN LANJUT MENGIKUT UNDANG-UNDANG BERKUATKUASA.','BERTINDAK ATAS TINDAKAN PENCEGAHAN BIL.27/2026 BERSABIT MAKLUMAT AWAM DENGAN MERUJUK ADUAN AJ-Petaling / 2026 / 04 / 0001 PADA 25 APRIL 2026 JAM LEBIH KURANG 12.35 MALAM SAYA BERSAMA-SAMA PPA AHMAD ADNIN AULA MAT ANI DAN PPA NORSYAFINA BINTI ABDUL RASIP TELAH MEMBUAT PEMERIKSAAN DIBILIK NOMBOR 1 HOTEL ARK DE GLORY YANG BERALAMAT NO.25 JALAN U3/3 (BK) SEKSYEN U3 40150 SHAH ALAM SELANGOR. HASIL PEMERIKSAAN DIDALAM BILIK NOMBOR 1 TELAH TEMUI 1 OYDS (L) DAN 1 OYDS (P) SAHAJA DAN HASIL SIASATAN MENDAPATI KEDUA-DUA OYDS TIADA APA-APA HUBUNGAN SUAMI ISTERI @ MAHRAM YANG SAH. BUTIRAN OYDS ADALAH SEPERTI BERIKUT:-\nOYDS (L) : MUHAMAD RIZAL BIN ABDULLAH\nNO.K/P : 930602-14-6631\nOYDS (P) : AININ SOFIYA BINTI AHMAD SHAFIEE\nNO.K/P: 980829-43-5046\nTELAH TERANGKAN KESALAHAN DAN TAHAN KEDUA-DUA OYDS DIBAWAH SEK.29 (1) A & B EJSS 9/95 (KHALWAT). ADA AMBIL RESIT DAFTAR MASUK HOTEL DAN REKOD DIBORANG BONGKARAN NO.E00889. BAWA OYDS KE HOTLINE JAIS SHAH ALAM UNTUK TINDAKAN SELANJUTNYA. OYDS DIBENARKAN IKAT JAMIN (LISAN) RM3000.00 DENGAN SETIAP SEORANG SATU PENJAMIN. SEKIAN REPOT SAYA.',NULL,NULL,NULL,'ada','tiada',NULL,NULL,NULL,NULL,'AJ-Petaling/2026/04/0001','[]',NULL,'2026-04-25 00:49:02',NULL,'2026-05-04 10:12:25',NULL,NULL),(2,'AJ','KES-Petaling/2026/04/0002',NULL,2026,1,'Petaling',NULL,59,86,86,NULL,26,NULL,'FNA',NULL,'Selesai Dengan Kes',NULL,NULL,NULL,NULL,NULL,'ada','Pegawai Penguatkuasa Agama',1,1,NULL,'2026-04-25 00:20:00','2026-04-25 00:25:00','2026-04-25 02:35:00','2026-04-29 09:00:00','2026-12-09','2026-04-25 00:55:00',NULL,NULL,'LAKSANA TINDAKAN LANJUT MENGIKUT UNDANG-UNDANG BERKUATKUASA.','PADA 25HB. APRIL 2026, JAM 12.35 MALAM, BERTINDAK ATAS ADUAN AJ-PETALING/2026/04/0002 SAYA BERSAMA PPA ZULHASYIRIEN BIN AHMAD JAIS, PPA ARIF AIDID BIN YATNI @ BAHARI DAN PPA SITI NOOR FATHEMAH BINTI SAYUTI TELAH MELAKUKAN PEMERIKSAAN DI SEBUAH PREMIS HOTEL BUDGET BERALAMAT ARK HOTEL SUBANG AIRPORT, 25, JALAN U3/3, SEKSYEN U3, SHAH ALAM, SUBANG, 40150 SHAH ALAM, SELANGOR. HASIL PEMERIKSAAN DI BILIK BERNOMBOR 16 PADA JAM 12.37 MALAM,   KAMI TELAH MENAHAN SEORANG LELAKI (OYDS L) DAN SEORANG PEREMPUAN (OYDS P) SEPERTI BUTIRAN BERIKUT :-\nNAMA OYDS (L) : DINI ZULHELMI BIN AB AZIZ\nNO. K/P : 000514-10-1993\nALAMAT K/P : NO. 16, JALAN QAMARI U5/109A, NUSA SUBANG, SEKSYEN U5, 40150 SHAH ALAM, SELANGOR\n\nNAMA OYDS (P) : NUR SYAFIKAH AYSRAH BINTI HALMIZAL\nNO. K/P : 030430-08-0168\nALAMAT K/P : NO. 3, HALA SUNLIGHT, TAMAN SUNLIGHT, 31650 IPOH, PERAK\nKEDUA-DUA OYDS DITAHAN KERANA DISYAKI MELAKUKAN KESALAHAN DI BAWAH PERUNTUKAN SEKSYEN 29 (1) A & (B) ENAKMEN JENAYAH SYARIAH (SELANGOR) NO. 9 TAHUN 1995 - KHALWAT. TERDAPAT BARANG YANG DISITA DAN DIREKODKAN PADA BORANG BONGKARAN BERNOMBOR E04800 ATAS NAMA OYDS (L). KEDUA-DUA OYDS DI BAWA KE BILIK GERAKAN, BAHAGIAN PENGURUSAN PENGUATKUASAAN JAIS, SHAH ALAM UNTUK TINDAKAN SELANJUTNYA SERTA KEDUA-DUA OYDS DIBENAR IKAT JAMIN DENGAN SEORANG PENJAMIN SETIAP SEORANG (JAMINAN LISAN).  SEKIAN LAPORAN SAYA.',NULL,NULL,NULL,'ada','tiada',NULL,NULL,NULL,NULL,'AJ-Petaling/2026/04/0002','[]',NULL,'2026-04-25 00:55:08',NULL,'2026-05-04 10:19:01',NULL,NULL),(3,'AJ','KES-Klang/2026/04/0003',NULL,2026,4,'Klang',NULL,59,12,12,NULL,26,NULL,'FNA',NULL,'Selesai Dengan Kes',NULL,NULL,NULL,NULL,NULL,'ada','Pegawai Penguatkuasa Agama',1,1,NULL,'2026-04-25 00:18:00','2026-04-25 00:23:00','2026-04-25 02:30:00','2026-04-25 02:40:00','2026-11-03','2026-04-25 01:00:00',NULL,NULL,'LAKSANA TINDAKAN LANJUT MENGIKUT UNDANG-UNDANG BERKUATKUASA.','BERTINDAK ATAS TINDAKAN PENCEGAHAN SIRI 2/2026 BERSABIT ADUAN AJ-KLANG/2026/04/0003 PADA 25.4.2026 L/K PUKUL 1.10 PAGI SAYA BERSAMA PPA NOR HAFIZ DAN PPA WAN HASNIDA TELAH MEMBUAT PEMERIKSAAN DI DALAM BILIK NO. 111, SUPER OYO 340 COMFORT HOTEL 196E, JALAN SENTOSA 53, OFF, JALAN SUNGAI PUTUS, 41050 KLANG, SELANGOR. HASIL PEMERIKSAAN MENDAPATI OYDS L DAN OYDS P BERADA DI DALAM BILIK TERSEBUT. BUTIRAN OYDS ADALAH SEPERTI BERIKUT :\n1) OYDS L  : MUHAMMAD SHAFIQ HAFIKI BIN SALLEH NO. K/P : 970623115005\n2) OYDS P : JAIZAH BINTI HISHAM NO. K/P ; 001210110692\nHASIL SIASATAN MENDAPATI OYDS L DAN OYDS P TIADA HUBUNGAN SUAMI ISTERI YANG SAH DAN TIADA HUBUNGAN MAHRAM YANG SAH. KEDUA-DUA OYDS DITAHAN DI BAWAH KESALAHAN KHALWAT SEKSYEN 29 (1) A&B EJSS NO. 9/95. ADA MENGAMBIL BARANG KES NO. SIRI BORANG BONGKARAN : E 02148.  KEDUA-DUA OYDS DIBAWA KE PAID KLANG UNTUK TINDAKAN SETERUSNYA. KAMI BERTINDAK ATAS NIAT SUCI HATI MELAKSANAKAN TUGAS DI BAWAH SEKSYEN 209 ETJSS 2003. SEKIAN LAPORAN SAYA.',NULL,NULL,NULL,'ada','tiada',NULL,NULL,NULL,NULL,'AJ-Klang/2026/04/0003','[]',NULL,'2026-04-25 01:18:45',NULL,'2026-05-04 10:49:57',NULL,NULL),(4,'AJ','KES-Petaling/2026/04/0004',NULL,2026,1,'Petaling',NULL,59,108,108,NULL,26,NULL,'FNA',NULL,'Selesai Dengan Kes',NULL,NULL,NULL,NULL,NULL,'ada','Pegawai Penguatkuasa Agama',1,1,NULL,'2026-04-25 00:25:00','2026-04-25 00:30:00','2026-04-25 02:40:00','2026-04-28 09:00:00','2026-12-09','2026-04-25 01:00:00',NULL,NULL,'LAKSANA TINDAKAN LANJUT MENGIKUT UNDANG-UNDANG BERKUATKUASA.','PADA TARIKH 25HB. APRIL 2026 L/K JAM 1.07 PAGI, BERTINDAK BERDASARKAN ADUAN AJ-Petaling / 2026 / 04 / 0004, SAYA BERSAMA-SAMA PPA MOHD AZWAN BIN ISMAIL DAN PPA NURUL SHAZREENA BINTI KAIMIN TELAH MELAKUKAN PEMERIKSAAN TERHADAP BILIK BERNOMBOR 211, UPTOWN HOTEL MANAGEMENT SDN BHD, NO. 1, JALAN U3/5 (BK), SEKSYEN U3, 40150 SHAH ALAM, SELANGOR. HASIL PEMERIKSAAN, KAMI TELAH MENAHAN SEORANG LELAKI (OYDS L) DAN SEORANG PEREMPUAN (OYDS P) SEPERTI BUTIRAN BERIKUT :-\nOYDS(L)\nNAMA : ZULHAZRUL IZWAN BIN ABU HASAN\nNO.K/P : 880722-08-6335\nALAMAT : DCD03-14-06 PANGSAPURI DE CENDANA, NO.7, PERSIARAN SETIA MAKMUR, SETIA ALAM, SEKSYEN U13, 40170 SHAH ALAM, SELANGOR\n\nOYDS(P)\nNAMA : SHAKILLA AURELIA RAHMAN\nNO. PASSPORT : E8289515\nWARGANEGARA : INDONESIA\nOYDS(L) DAN OYDS(P) DITAHAN KERANA DISYAKI TELAH MELAKUKAN KESALAHAN DI BAWAH SEKSYEN  29 (1) (a) & (b) ENAKMEN JENAYAH SYARIAH SELANGOR NO.9 TAHUN 1995 IAITU KHALWAT. TERDAPAT BARANG YANG TELAH DISITA DAN DIREKODKAN PADA BORANG BONGKARAN BERNOMBOR  E03874. KEDUA-DUA OYDS TELAH DIBAWA KE HOTLINE 24 JAM, BAHAGIAN PENGURUSAN PENGUATKUASAAN, JAIS, SHAH ALAM UNTUK TINDAKAN SELANJUTNYA. SEKIAN LAPORAN SAYA.',NULL,NULL,NULL,'ada','tiada',NULL,NULL,NULL,NULL,'AJ-Petaling/2026/04/0004','[]',NULL,'2026-04-25 01:28:29',NULL,'2026-05-04 10:23:34',NULL,NULL),(5,'AJ','KES-Sepang/2026/04/0005',NULL,2026,6,'Sepang',NULL,61,18,18,NULL,26,NULL,'FNA',NULL,'Selesai Tanpa Kes',NULL,'PP Unit Gerakan',NULL,NULL,NULL,'tiada',NULL,NULL,NULL,NULL,'2026-04-26 23:54:00','2026-04-27 23:59:00','2026-04-26 01:50:00',NULL,NULL,'2026-04-26 23:54:00',NULL,NULL,'LAKSANAKAN ADUAN SEKIRANYA PENGADU MENGESAHAKAN KEJADIAN MENGIKUT UNDANG UNDANG SEDIA ADA','PADA 26/4/2026 JAM LEBIH KURANG 12.40 PAGI BERSABIT AJ-SEPANG/2026/04/0013 SAYA BERSAMA PPA ALFIAN BIN AHMAD, PPA ABDUL RASYID BIN HUSSAIN, PUAN NURULHIDAYAH BINTI MAHYUDIN DAN CIK NOR FARIDAH BINTI AB WAHAB TELAH MELAKSANAKAN PEMERIKSAAN DI SEBUAH RUMAH DI ALAMAT A-6-21, PANGSAPURI TOPAZ, TAMAN TOPAZ, 43800 DENGKIL, SELANGOR. HASIL PEMERIKSAAN KAMI MENEMUI SEORANG PENGHUNI PEREMPUAN BERNAMA SITI FAMEIZA BINTI RAHIMI NO.K/P 920728-03-5030. TURUT TINGGAL BERSAMA 3 ORANG ANAK PENGHUNI BERNAMA (K1) NUR DANIA MAISARAY BINTI YUSREE NO.K/P 111003-03-0582, (K2) NUR RABIATUL ADDAWIYAH BINTI LUQMAN NO.MYKID 180619-03-0942 DAN (K3) LUQMIE BIN LUQMAN NO.MYKID 230710-03-0479. TIADA TANGKAPAN DIBUAT KERANA TIADA PERLANGGARAN KESALAHAN SYARIAH BERLAKU. TIADA BARANG KES DIAMBIL. SETELAH BERPUAS HATI, KAMI BERTINDAK MENINGGALKAN LOKASI. SEKIAN LAPORAN SAYA.',NULL,NULL,NULL,'tiada','tiada',NULL,NULL,NULL,NULL,'AJ-Sepang/2026/04/0005','[]',NULL,'2026-04-25 23:49:40',NULL,'2026-04-30 11:46:25',NULL,NULL),(6,'AJ','KES-Klang/2026/04/0006',NULL,2026,4,'Klang',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NFA',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-26 07:55:27',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'AJ-Klang/2026/04/0014','[]',NULL,'2026-04-26 07:55:27',NULL,'2026-05-08 09:03:47',NULL,NULL),(7,'AJ','KES-Sabak Bernam/2026/04/0007',NULL,2026,9,'Sabak Bernam',NULL,60,4,3,NULL,26,NULL,'FNA',NULL,'Selesai Dengan Kes',NULL,NULL,NULL,NULL,NULL,'ada','Pegawai Penguatkuasa Agama',1,1,NULL,'2026-04-26 09:19:00','2026-04-26 21:19:00','2026-04-26 22:35:00','2026-04-27 09:30:00','2026-10-15','2026-04-26 09:19:00',NULL,'2026-05-06 09:26:13','LAKSANA TINDAKAN  LANJUT  MENGIKUT UNDANG-UNDANG BERKUATKUASA.','PADA 26 APRIL 2026 LEBIH KURANG JAM 10.20 MALAM, BERDASARKAN ADUAN AWAM AJ-SABAK BERNAM / 2026/04/0015, SAYA BERSAMA KUPN MUHAMMAD SUHAILI BIN SAJIMAN, PPA NADIAH BINTI HATIM DAN PPA SITI RAHMAH BINTI ANOR TELAH MELAKSANAKAN ADUAN AWAM DI LOKASI BERALAMAT : RUMAH SEWA NO 3, BERSEBELAHAN MASJID MARZUKIAH, JALAN PARIT 13 KAMPUNG LUBUK PUSING ,45300 SUNGAI BESAR ,SELANGOR.\n\nKAMI TIBA DI LOKASI PADA JAM 10.30 MALAM. KUPN MUHAMMAD SUHAILI BIN SAJIMAN TELAH MEMBERI SALAM DAN KEMUDIAN PINTU TELAH DIBUKA OLEH PEREMPUAN (OYDSP). SAYA DAN PPA SITI RAHMAH YANG DIARAHKAN BERKAWAL DI BAHAGIAN BELAKANG RUMAH TELAH MASUK MELALUI PINTU BELAKANG KE DALAM RUMAH. KUPN MUHAMMAD SUHAILI BIN SAJIMAN TELAH MEMPERKENALKAN DIRI SEBAGAI PEGAWAI PENGUATKUASA JAIS DAN MEMINTA IZIN MASUK BAGI MEMBUAT PEMERIKSAAN.\n\nSETELAH ITU, KAMI TERUS MEMBUAT PEMERIKSAAN DI DALAM RUMAH BAGI MENJALANKAN PEMERIKSAAN LANJUT .\n\nHASIL PEMERIKSAAN LANJUT, KAMI TELAH MENEMUI SEPASANG LELAKI DAN PEREMPUAN DI DALAM RUMAH TERSEBUT.\n\nBUTIRAN OYDSL ADALAH SEPERTI BERIKUT :\nNAMA : MOHD ZAMRI BIN ABD BAKI\nNO KAD PENGENALAN : 900204-10-5781\nALAMAT : JALAN KENANGAN KAMPUNG BUKIT KERAYONG 42200 KAPAR SELANGOR\n\nBUTIRAN OYDSP ADALAH SEPERTI BERIKUT :\n\nNAMA : NURUL SYUHADA BINTI KHAIRULNIZAM\nNO KAD PENGENALAN : 971017-10-5370\nALAMAT : RUMAH SEWA NO 3,BERSEBELAHAN MASJID MARZUKIAH,JALAN PARIT 13,KAMPUNG LUBUK PUSING, 45300 SUNGAI BESAR SELANGOR\n\nHASIL SOAL SIASAT MENDAPATI KEDUA OYDS TIADA HUBUNGAN MAHRAM ATAU SUAMI ISTERI YANG SAH. SAYA TELAH MENERANGKAN KESALAHAN KEPADA KEDUA OYDS DAN TELAH DITAHAN DI BAWAH SEKSYEN 29 (1) A & B ENAKMEN JENAYAH SYARIAH SELANGOR NO 9 TAHUN 1995 (KHALWAT).\n\nKEDUA OYDS DIARAHKAN BERSIAP DAN DIBAWA KE UNIT PENGURUSAN PENGUATKUASAAN PAID SABAK BERNAM UNTUK URUSAN SIASATAN DAN JAMINAN. KAMI KELUAR LOKASI DENGAN SELAMAT DAN TIADA MENGAMBIL APA-APA BARANG KES. SEKIAN LAPORAN SAYA.',NULL,NULL,NULL,'tiada','tiada',NULL,NULL,NULL,NULL,'AJ-Sabak Bernam/2026/04/0015','[]',NULL,'2026-04-26 21:24:58',NULL,'2026-05-07 14:40:12',NULL,NULL),(8,'AJ','KES-Petaling/2026/04/0008',NULL,2026,1,'Petaling',NULL,60,69,102,NULL,26,NULL,'OP',NULL,'Other','KSJS - SIASAT',NULL,NULL,NULL,NULL,'ada','Orang Awam',1,1,NULL,'2026-04-27 19:52:00','2026-04-27 20:00:00','2026-05-04 12:00:00','2026-05-04 09:20:00','2027-01-07','2026-04-27 19:52:00',NULL,NULL,'SILA DAPATKAN MINIT / ARAHAN DARIPADA KPPA','Bertindak berdasarkan maklumat awam No. AJ-Petaling/2026/04/0009 dan bersabit Nombor Repot 004876/26-Bandar Kinrara , Pada 04/05/2026 jam lebih kurang 09.20 pagi saya telah membuat siasatan terhadap 2 orang OYDS yang telah hadir dihadapan saya dan nama OYDS adalah seperti berikut:-\n\nOYDS(L) : Muhammad Zamir Raziq Bin Mohd Zamri\nNo.K/P : 070523-14-1181\n\nOYDS(P) : Nur Qaisara Binti Abu Seman\nNo.K/P : 110113-05-0336\n\nHasil siasatan mendapati kedua-dua OYDS telah di syaki melakukan kesalahan khalwat di dalam sebuah rumah beralamat No.23, Jalan BK 3/1A, Bandar Kinrara, 47180 Puchong ,Selangor. Kesalahan tersebut telah dilakukan pada 27/04/2026 jam lebih kurang 1.00 tengahari. Kedua-dua OYDS telah di tahan oleh seorang jiran (orang awam) bernama Muhd Ikhmaluddin bin Azamudin No.K/P: 921118-08-6505. Saksi penangkap tersebut telah membawa kedua-dua OYDS ke balai polis yang berhampiran (rujuk laporan polis) untuk tindakan dan siasatan lanjut.\n\nHasil siasatan terhadap saksi penangkap dan kedua-dua OYDS mendapati, wujud kesalahan disyaki khalwat seperti dinyatakan di atas. Saya telah menahan kedua-dua OYDS di bawah Seksyen 29 1(a)(b) EJSS 9/95 (Khalwat). Kedua-dua OYDS dibenarkan di ikat jamin dengan setiap seorang satu penjamin. Sekian, laporan saya','TINDAKAN TELAH DILAKSANAKAN OLEH PENGADU DAN PENGADU TELAH BERTINDAK KE PREMIS/LOKASI KEJADIAN DAN HASIL PEMERIKSAAN MENDAPATI ADA BERLAKU PELANGGARAN KESALAHAN ENAKMEN JENAYAH SYARIAH (SELANGOR) NO.9 TAHUN 1995. PENGADU TELAH MEMBUAT TANGKAPAN DAN TELAH BAWA OYDS KE BALAI POLIS BANDAR KINRARA, PUCHONG. RUJUK 004876/26- BANDAR KINRARA',NULL,NULL,'tiada','ada','tiada',NULL,NULL,NULL,'AJ-Petaling/2026/04/0009','[]',NULL,'2026-04-27 19:52:18',69,'2026-06-24 16:18:10',NULL,NULL),(9,'AJ','KES-Hulu Langat/2026/04/0009',NULL,2026,3,'Hulu Langat',45,60,49,122,NULL,26,NULL,'FNA','Proses Siasatan','Selesai Dengan Kes',NULL,'PP Unit Gerakan',NULL,NULL,NULL,'ada','Pegawai Penguatkuasa Agama',0,1,NULL,'2026-04-28 00:26:00','2026-04-28 00:31:00','2026-04-28 02:30:00','2026-05-12 09:00:00','2026-10-27','2026-04-28 00:26:00',NULL,NULL,'LAKSANA ADUAN DENGAN BERHEMAH MENGIKUT UNDANG UNDANG SEDIA ADA','PADA 28/04/2026 L/K JAM 0055 HRS BERSABIT  ADUAN AJ-HULU LANGAT/2026/04/0029 SAYA BERSAMA PPA MOHD AZIZI BIN MOHAMAD SANI DAN PPA MUHAMAD ZAIDI BIN HAMZAH  TELAH MEMBUAT PEMERIKSAAN DI ALAMAT  BILIK 2, C110, JALAN TENAGA 21,TAMAN TENAGA, 43000 KAJANG, SELANGOR. HASIL PEMERIKSAAN TELAH MENAHAN :\n\nOYDS (P) : NURFAERSYA ASYIKIN BINTI ERWAN\nNO. K/P   : 040515-06-0480\n\nBERSAMA PASANGAN BUKAN ISLAM:\n\nNAMA     : FANDY ANAK ANGOI\nNO. K/P : 040812-13-0027\n\nDIBAWAH SEKSYEN 29 (1) B EJSS 9/95 KERANA DISYAKI KHALWAT. OYDS P TELAH DIBAWA KE U